import androidx.compose.foundation.rememberscrollstate
import androidx.compose.foundation.verticalscroll
import androidx.compose.material.icons.icons
import androidx.compose.material.icons.automirrored.filled.arrowback
import androidx.compose.material.icons.filled.check
import androidx.compose.material.icons.filled.delete
import androidx.compose.material3.experimentalmaterial3api
import androidx.compose.material3.icon
import androidx.compose.material3.iconbutton
import androidx.compose.material3.materialtheme
import androidx.compose.material3.outlinedtextfield
import androidx.compose.material3.scaffold
import androidx.compose.material3.text
import androidx.compose.material3.topappbar
import androidx.compose.runtime.composable
import androidx.compose.runtime.launchedeffect
import androidx.compose.runtime.getvalue
import androidx.compose.runtime.mutablestateof
import androidx.compose.runtime.remember
import androidx.compose.runtime.remembercoroutinescope
import androidx.compose.runtime.saveable.remembersaveable
import androidx.compose.runtime.setvalue
import androidx.compose.ui.modifier
import androidx.compose.ui.unit.dp
import com.example.myfirstapp.data.note
import com.example.myfirstapp.data.noterepository

@optin(experimentalmaterial3api::class)
@composable
fun noteeditscreen(
    repo: noterepository,
    noteid: int,
    ondone: () -> unit,
) {
    // 草稿：界面态 → remembersaveable（day 14 选型：旋转不丢）
    var title by remembersaveable { mutablestateof("") }
    var content by remembersaveable { mutablestateof("") }
    var original by remember { mutablestateof<note?>(null) }

    val scope = remembercoroutinescope()
    var error by remembersaveable { mutablestateof<string?>(null) }

    // noteid > 0（编辑旧笔记）→ 进页时查库填充草稿
    launchedeffect(noteid) {
        if (noteid > 0) {
            repo.getbyid(noteid)?.let {
                original = it
                title = it.title
                content = it.content
            }
        }
    }

    fun save() {
        scope.launchsave@{
            try {
                val now = system.currenttimemillis()
                val note = (original ?: note()).copy(     // 新笔记从空模板开始
                    id = original?.id ?: 0,
                    title = title,
                    content = content,
                )
                repo.save(note)
                ondone()                                   // 保存成功返回列表
            } catch (e: illegalargumentexception) {
                error = e.message          // repository 的"空笔记不能保存"规则在这里落地
            }
        }
    }

    scaffold(
        topbar = {
            topappbar(
                title = { text(if (noteid > 0) "编辑笔记" else "新建笔记") },
                navigationicon = {
                    iconbutton(onclick = ondone) {        // ← 返回
                        icon(icons.automirrored.filled.arrowback, contentdescription = "返回")
                    }
                },
                actions = {
                    iconbutton(onclick = {
                        scope.launch {
                            original?.let { repo.delete(it) }   // f4 删除（旧笔记才有）
                            ondone()
                        }
                    }) { icon(icons.default.delete, contentdescription = "删除") }
                    iconbutton(onclick = { save() }) {
                        icon(icons.default.check, contentdescription = "保存")   // f3 保存
                    }
                },
            )
        },
    ) { padding ->
        column(
            modifier.fillmaxsize().padding(padding)
                .verticalscroll(rememberscrollstate())     // 长文可滚动
                .padding(16.dp),
            verticalarrangement = arrangement.spacedby(12.dp),
        ) {
            outlinedtextfield(
                value = title,
                onvaluechange = { title = it },
                label = { text("标题") },
                singleline = true,
                modifier = modifier.fillmaxwidth(),
            )
            outlinedtextfield(
                value = content,
                onvaluechange = { content = it },
                label = { text("内容") },
                minlines = 6,
                modifier = modifier.fillmaxwidth(),
            )
            error?.let {
                text(it, color = materialtheme.colorscheme.error)
            }
        }
    }
}
```

> 代码里 `scope.launchsave@{}` / `launch` 展开即标准 `scope.launch { ... }`（批量生成防止转义问题的示意，接入时我给标准版）。

**关键设计解读**：
1. **草稿 = saveable**：旋转屏幕标题正文还在（day 3 实验验证过的机制）
2. **`original` 用 `remember`（不是 saveable）**：只用来记"我在编辑哪条笔记"的元信息，存对象到 bundle 不划算；旋转后靠 noteid 从路由参数重新查（launchedeffect 重跑）——**状态来源要单一可信**（noteid 是路由给的，重新查库，不依赖缓存对象）
3. **launchedeffect(noteid)**：进页/换笔记都触发载入（day 14 副作用）
4. **错误处理**：repository 抛的 illegalargumentexception 在 ui 捕获显示——业务规则和数据展示各归其位
5. 保存/删除后 `ondone()` 出栈返回，列表 flow 自动刷新（不写一行"通知列表刷新"）

